-- Deduplication, search-result and filter schemas for the master register.
--
-- Dedup leans on foundational_id and the disability certificate number
-- because a disability registry routinely receives the same person twice
-- through different referral channels (health facility, OPD, social
-- registry transfer), often with names spelled differently each time.
--
-- The filter dropdowns list their options inline. That is a deliberate
-- exception to the "code lists live in g2p_attribute_values" rule: these
-- are enum values the ORM will reject if they differ, so they must track
-- models/enums.py, not a country pack.
INSERT INTO "public"."g2p_register_schemas" ("register_id","deduplicate_schema","search_result_schema","filter_schema") VALUES 
('a0000000-0000-4000-8000-000000000001','[{"field_name": "foundational_id", "match_type": "exact", "weight": 0.35}, {"field_name": "disability_certificate_number", "match_type": "exact", "weight": 0.25}, {"field_name": "first_name", "match_type": "fuzzy", "weight": 0.15}, {"field_name": "last_name", "match_type": "fuzzy", "weight": 0.15}, {"field_name": "birth_date", "match_type": "exact", "weight": 0.1}]','[{"field_name": "functional_record_id", "display_label": "Person ID", "order": 1}, {"field_name": "full_name", "display_label": "Full Name", "order": 2}, {"field_name": "foundational_id", "display_label": "Foundational ID", "order": 3}, {"field_name": "gender", "display_label": "Gender", "order": 4}, {"field_name": "birth_date", "display_label": "Birth Date", "order": 5}, {"field_name": "disability_status", "display_label": "Disability Status", "order": 6}, {"field_name": "disability_status_level", "display_label": "Level", "order": 7}, {"field_name": "support_needs_level", "display_label": "Support Needs", "order": 8}, {"field_name": "has_unmet_support_need", "display_label": "Unmet Need", "order": 9}, {"field_name": "address_line_1", "display_label": "Address", "order": 10}]','[{"field_name": "full_name", "display_label": "Full Name", "filter_type": "text", "order": 1, "allowed_operators": ["eq", "contains"]}, {"field_name": "foundational_id", "display_label": "Foundational ID", "filter_type": "text", "order": 2, "allowed_operators": ["eq"]}, {"field_name": "disability_certificate_number", "display_label": "Certificate No.", "filter_type": "text", "order": 3, "allowed_operators": ["eq", "contains"]}, {"field_name": "disability_status", "display_label": "Disability Status", "filter_type": "dropdown", "order": 4, "allowed_operators": ["eq", "in"], "options_source": [{"value": "ASSESSED_DISABLED", "label": "ASSESSED_DISABLED"}, {"value": "ASSESSED_NOT_DISABLED", "label": "ASSESSED_NOT_DISABLED"}, {"value": "PENDING_ASSESSMENT", "label": "PENDING_ASSESSMENT"}, {"value": "SELF_DECLARED", "label": "SELF_DECLARED"}, {"value": "UNKNOWN", "label": "UNKNOWN"}]}, {"field_name": "disability_status_level", "display_label": "Severity Level", "filter_type": "dropdown", "order": 5, "allowed_operators": ["eq", "in"], "options_source": [{"value": "NONE", "label": "NONE"}, {"value": "MILD", "label": "MILD"}, {"value": "MODERATE", "label": "MODERATE"}, {"value": "SEVERE", "label": "SEVERE"}, {"value": "PROFOUND", "label": "PROFOUND"}]}, {"field_name": "support_needs_level", "display_label": "Support Needs Level", "filter_type": "dropdown", "order": 6, "allowed_operators": ["eq", "in"], "options_source": [{"value": "INDEPENDENT", "label": "INDEPENDENT"}, {"value": "INTERMITTENT_SUPPORT", "label": "INTERMITTENT_SUPPORT"}, {"value": "LIMITED_SUPPORT", "label": "LIMITED_SUPPORT"}, {"value": "EXTENSIVE_SUPPORT", "label": "EXTENSIVE_SUPPORT"}, {"value": "PERVASIVE_SUPPORT", "label": "PERVASIVE_SUPPORT"}]}, {"field_name": "has_unmet_support_need", "display_label": "Has Unmet Support Need", "filter_type": "boolean", "order": 7, "allowed_operators": ["eq"]}, {"field_name": "unmet_support_needs_count", "display_label": "Unmet Need Count", "filter_type": "number", "order": 8, "allowed_operators": ["eq", "gt", "gte", "lt", "lte"]}, {"field_name": "housing_type", "display_label": "Housing Type", "filter_type": "dropdown", "order": 9, "allowed_operators": ["eq", "in"], "options_source": [{"value": "INDEPENDENT_HOME", "label": "INDEPENDENT_HOME"}, {"value": "FAMILY_HOME", "label": "FAMILY_HOME"}, {"value": "SUPPORTED_LIVING", "label": "SUPPORTED_LIVING"}, {"value": "GROUP_HOME", "label": "GROUP_HOME"}, {"value": "RESIDENTIAL_INSTITUTION", "label": "RESIDENTIAL_INSTITUTION"}, {"value": "HOSPITAL_LONG_STAY", "label": "HOSPITAL_LONG_STAY"}, {"value": "TEMPORARY_SHELTER", "label": "TEMPORARY_SHELTER"}, {"value": "HOMELESS", "label": "HOMELESS"}, {"value": "OTHER", "label": "OTHER"}]}, {"field_name": "employment_status", "display_label": "Employment Status", "filter_type": "dropdown", "order": 10, "allowed_operators": ["eq", "in"], "options_source": [{"value": "EMPLOYED", "label": "EMPLOYED"}, {"value": "SELF_EMPLOYED", "label": "SELF_EMPLOYED"}, {"value": "SHELTERED_EMPLOYMENT", "label": "SHELTERED_EMPLOYMENT"}, {"value": "SUPPORTED_EMPLOYMENT", "label": "SUPPORTED_EMPLOYMENT"}, {"value": "UNEMPLOYED_SEEKING", "label": "UNEMPLOYED_SEEKING"}, {"value": "UNEMPLOYED_NOT_SEEKING", "label": "UNEMPLOYED_NOT_SEEKING"}, {"value": "STUDENT", "label": "STUDENT"}, {"value": "RETIRED", "label": "RETIRED"}, {"value": "UNABLE_TO_WORK", "label": "UNABLE_TO_WORK"}, {"value": "OTHER", "label": "OTHER"}]}, {"field_name": "gender", "display_label": "Gender", "filter_type": "dropdown", "order": 11, "allowed_operators": ["eq", "in"], "options_source": [{"value": "MALE", "label": "MALE"}, {"value": "FEMALE", "label": "FEMALE"}, {"value": "OTHERS", "label": "OTHERS"}, {"value": "UNKNOWN", "label": "UNKNOWN"}]}, {"field_name": "certificate_expiry_date", "display_label": "Certificate Expiry", "filter_type": "date", "order": 12, "allowed_operators": ["eq", "gt", "gte", "lt", "lte"]}]')
ON CONFLICT ("register_id") DO NOTHING;
